// oauth2.rs - OAuth2 Authorization Code Flow with PKCE
use oauth2::basic::BasicClient;\use oauth2::{
    AuthUrl, TokenUrl, ClientId, ClientSecret, RedirectUrl,
    AuthorizationCode, CsrfToken, PkceCodeChallenge, PkceCodeVerifier,
    Scope, TokenResponse,
};\use reqwest::Client as HttpClient;\use serde::{Deserialize, Serialize};\use std::collections::HashMap;\use std::sync::Arc;\use tokio::sync::RwLock;\use thiserror::Error;\use url::Url;

#[derive(Error, Debug)]
pub enum OAuth2Error {
    #[error("Invalid redirect URI")]
    InvalidRedirectUri,
    #[error("PKCE verification failed")]
    PkceVerificationFailed,
    #[error("State mismatch: CSRF attack suspected")]
    StateMismatch,
    #[error("Token exchange failed: {0}")]
    TokenExchangeFailed(String),
    #[error("Token storage error: {0}")]
    TokenStorageError(String),
    #[error("HTTP error: {0}")]
    HttpError(#[from] reqwest::Error),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OAuth2Tokens {
    pub access_token: String,
    pub refresh_token: Option<String>,
    pub expires_in: Option<u64>,
    pub token_type: String,
    pub scope: Option<String>,
    pub id_token: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StoredTokens {
    pub tokens: OAuth2Tokens,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub pkce_verifier: Option<String>,
}

#[derive(Clone)]
pub struct OAuth2Service {
    client: BasicClient,
    http_client: HttpClient,
    token_store: Arc<RwLock<HashMap<String, StoredTokens>>>,
    redirect_url: String,
}

impl OAuth2Service {
    pub fn new(
        client_id: String,
        client_secret: String,
        auth_url: String,
        token_url: String,
        redirect_url: String,
    ) -> Result<Self, OAuth2Error> {
        let auth_url = AuthUrl::new(auth_url)?;
        let token_url = TokenUrl::new(token_url)?;
        let redirect_url_parsed = RedirectUrl::new(redirect_url.clone())?;

        let client = BasicClient::new(
            ClientId::new(client_id),
            Some(ClientSecret::new(client_secret)),
            auth_url,
            Some(token_url),
        ).set_redirect_uri(redirect_url_parsed);

        Ok(Self {
            client,
            http_client: HttpClient::new(),
            token_store: Arc::new(RwLock::new(HashMap::new())),
            redirect_url,
        })
    }

    pub fn authorize_url(&self, scopes: Vec<String>, state: Option<String>) -> (Url, CsrfToken, PkceCodeVerifier) {
        let (pkce_challenge, pkce_verifier) = PkceCodeChallenge::new_random_sha256();
        let (auth_url, csrf_token) = self.client
            .authorize_url(CsrfToken::new_random)
            .add_scopes(scopes.into_iter().map(Scope::new))
            .set_pkce_challenge(pkce_challenge)
            .url();
        (auth_url, csrf_token, pkce_verifier)
    }

    pub async fn exchange_code(
        &self,
        code: String,
        pkce_verifier: PkceCodeVerifier,
        expected_state: CsrfToken,
        received_state: CsrfToken,
    ) -> Result<OAuth2Tokens, OAuth2Error> {
        if expected_state.secret() != received_state.secret() {
            return Err(OAuth2Error::StateMismatch);
        }

        let token_result = self.client
            .exchange_code(AuthorizationCode::new(code))
            .set_pkce_verifier(pkce_verifier)
            .request_async(&self.http_client)
            .await
            .map_err(|e| OAuth2Error::TokenExchangeFailed(e.to_string()))?;

        Ok(OAuth2Tokens {
            access_token: token_result.access_token().secret().clone(),
            refresh_token: token_result.refresh_token().map(|t| t.secret().clone()),
            expires_in: token_result.expires_in().map(|d| d.as_secs()),
            token_type: token_result.token_type().to_string(),
            scope: token_result.scopes().map(|s| s.iter().map(|s| s.to_string()).collect::<Vec<_>>().join(" ")),
            id_token: token_result.id_token().map(|t| t.to_string()),
        })
    }

    pub async fn refresh_access_token(&self, user_id: &str) -> Result<OAuth2Tokens, OAuth2Error> {
        let mut store = self.token_store.write().await;
        let stored = store.get_mut(user_id).ok_or_else(|| OAuth2Error::TokenStorageError("No tokens found".to_string()))?;

        let refresh_token = stored.tokens.refresh_token.as_ref().ok_or_else(||
            OAuth2Error::TokenStorageError("No refresh token available".to_string()))?;

        let token_result = self.client
            .exchange_refresh_token(&oauth2::RefreshToken::new(refresh_token.clone()))
            .request_async(&self.http_client)
            .await
            .map_err(|e| OAuth2Error::TokenExchangeFailed(e.to_string()))?;

        let new_tokens = OAuth2Tokens {
            access_token: token_result.access_token().secret().clone(),
            refresh_token: token_result.refresh_token().map(|t| t.secret().clone()).or(Some(refresh_token.clone())),
            expires_in: token_result.expires_in().map(|d| d.as_secs()),
            token_type: token_result.token_type().to_string(),
            scope: token_result.scopes().map(|s| s.iter().map(|s| s.to_string()).collect::<Vec<_>>().join(" ")),
            id_token: token_result.id_token().map(|t| t.to_string()),
        };

        stored.tokens = new_tokens.clone();
        stored.created_at = chrono::Utc::now();
        Ok(new_tokens)
    }

    pub async fn get_valid_token(&self, user_id: &str) -> Result<String, OAuth2Error> {
        let store = self.token_store.read().await;
        if let Some(stored) = store.get(user_id) {
            if let Some(expires_in) = stored.tokens.expires_in {
                let expires_at = stored.created_at + chrono::Duration::seconds(expires_in as i64);
                if chrono::Utc::now() < expires_at - chrono::Duration::seconds(60) {
                    return Ok(stored.tokens.access_token.clone());
                }
            }
        }
        drop(store);
        let tokens = self.refresh_access_token(user_id).await?;
        Ok(tokens.access_token)
    }

    pub async fn store_tokens(&self, user_id: String, tokens: OAuth2Tokens, pkce_verifier: Option<PkceCodeVerifier>) {
        let mut store = self.token_store.write().await;
        store.insert(user_id, StoredTokens {
            tokens,
            created_at: chrono::Utc::now(),
            pkce_verifier: pkce_verifier.map(|v| v.secret().clone()),
        });
    }
